def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_aggressive = 0
    moderate_max = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid > moderate_max and bid <= 230:
                    moderate_max = float(bid)
                if bid >= 160 and opp.get('budget', 0) > 250:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, 18.0))

    units = int(supply / WATER_REQ)
    scarcity = units <= 1
    late_game = day >= 8

    urgent = False
    if hp <= 3:
        urgent = True
    if no_water >= 2:
        urgent = True
    if hp <= 5 and no_water >= 1:
        urgent = True
    if late_game and hp <= 6:
        urgent = True

    if urgent:
        target = max(92.0, moderate_max + 3.0)
        if rich_aggressive >= 2:
            target = max(target, 132.0)
        if hp <= 2 or no_water >= 3:
            target = max(target, 168.0)
        return float(min(budget, target))

    if scarcity:
        if hp >= 8 and no_water == 0:
            target = 8.0 if rich_aggressive >= 1 else 16.0
        elif hp >= 6:
            target = 28.0 if rich_aggressive >= 1 else 42.0
        else:
            target = max(70.0, moderate_max * 0.72)
    else:
        if hp >= 8 and no_water == 0:
            target = 22.0
        elif hp >= 6:
            target = 38.0
        else:
            target = 62.0

    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev < 120 and not scarcity:
            target = max(target, highest_prev + 2.0)
        elif highest_prev < 120 and hp <= 6:
            target = max(target, highest_prev + 4.0)

    reserve_floor = max(0.0, (10 - day) * 8.0)
    spend_cap = max(0.0, budget - reserve_floor)
    if urgent:
        spend_cap = budget

    bid = min(target, spend_cap if spend_cap > 0 else target, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opp = [o for o in opponents_status.values() if o.get('alive', False)]
    prev_bids = []
    for opp in alive_opp:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    max_prev_bid = max(prev_bids) if prev_bids else 0

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if hp <= 2 or no_water_days > 0:
        base_bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        base_bid = min(budget, DAILY_SALARY * 0.7)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.55)

    # Adjust based on opponent pressure
    if max_prev_bid > DAILY_SALARY * 0.8:
        target = max(base_bid, max_prev_bid + 1.0)
    elif max_prev_bid > DAILY_SALARY * 0.5:
        target = max(base_bid, max_prev_bid * 0.9)
    else:
        target = base_bid

    return min(budget, max(target, 1.0))
